@push('scripts')<script>function addIngredient(id){const box=document.getElementById('ingredients'+id);const n=box.children.length;const row=box.firstElementChild.cloneNode(true);row.querySelectorAll('select,input').forEach(el=>{el.name=el.name.replace('[0]','['+n+']');el.value='';});box.appendChild(row);}</script>@endpush
